class ResourceHandle {
    size_t size_;
public:
    // Explicit prevents unintended conversions from size_t
    explicit ResourceHandle(size_t s) : size_(s) {}

    // Multi-argument constructors do not need explicit
    ResourceHandle(size_t s, bool init) : size_(s) {}
};

// Valid (Explicit construction)
ResourceHandle rh1(100);

// Invalid (Implicit conversion blocked by 'explicit')
// ResourceHandle rh2 = 50; 

// Valid (Multiple arguments)
ResourceHandle rh3(50, true);
